+fn c_range(t: &Toolpath) -> (f64, f64) {
+    t.moves
+        .iter()
+        .filter_map(|m| m.rotary)
+        .fold((f64::INFINITY, f64::NEG_INFINITY), |(l, h), c| (l.min(c), h.max(c)))
+}
